{
  "states": [
    "Pending Transaction",
    "Final Response Sent"
  ],
  "transitions": [
    {
      "from": "Pending Transaction",
      "event": "CANCEL request received for INVITE",
      "action": "respond to original request with 487 (Request Terminated); respond to CANCEL with 200 (OK)",
      "to": "Final Response Sent"
    },
    {
      "from": "Pending Transaction",
      "event": "CANCEL request received for non-INVITE",
      "action": "respond to CANCEL with 200 (OK); no impact on original transaction processing",
      "to": "Pending Transaction"
    },
    {
      "from": "Final Response Sent",
      "event": "CANCEL request received",
      "action": "no effect on original request or session state; respond to CANCEL with 200 (OK)",
      "to": "Final Response Sent"
    }
  ]
}

{
  "states": [
    "Binding Registered",
    "Binding Removed"
  ],
  "transitions": [
    {
      "from": "",
      "event": "REGISTER request with Contact header field and expiration interval > 0",
      "action": "Registrar adds or updates binding in location service; returns 200 OK with Contact list",
      "to": "Binding Registered"
    },
    {
      "from": "Binding Registered",
      "event": "REGISTER request with Contact header field and expiration interval = 0",
      "action": "Registrar removes binding from location service; returns 200 OK with updated Contact list",
      "to": "Binding Removed"
    },
    {
      "from": "Binding Registered",
      "event": "Expiration interval elapses without refresh",
      "action": "Binding expires (soft state)",
      "to": "Binding Removed"
    },
    {
      "from": "Binding Registered",
      "event": "REGISTER request with Contact header field and expiration interval > 0 before expiration",
      "action": "Registrar updates expiration time of binding; returns 200 OK with Contact list",
      "to": "Binding Registered"
    },
    {
      "from": "",
      "event": "REGISTER request with Contact header field value '*' and Expires header field = 0",
      "action": "Registrar removes all bindings for address-of-record; returns 200 OK with empty or updated Contact list",
      "to": "Binding Removed"
    }
  ]
}

